package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.*;
import com.fasterxml.jackson.annotation.JsonIgnore;
import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
import com.fasterxml.jackson.core.type.Typeable;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.annotation.JsonPOJOBuilder;
import com.fasterxml.jackson.databind.cfg.ConfigOverride;
import com.fasterxml.jackson.databind.cfg.DeserializerFactoryConfig;
import com.fasterxml.jackson.databind.cfg.MapperFeature;
import com.fasterxml.jackson.databind.deser.BeanDeserializerBuilder;
import com.fasterxml.jackson.databind.deser.BeanDeserializerFactory;
import com.fasterxml.jackson.databind.deser.impl.*;
import com.fasterxml.jackson.databind.deser.impl.BeanPropertyDefinition;
import com.fasterxml.jackson.databind.deser.impl.CreatorProperty;
import com.fasterxml.jackson.databind.deser.impl.SettableBeanProperty;
import com.fasterxml.jackson.databind.deser.impl.StdDeserializer;
import com.fasterxml.jackson.databind.deser.std.ThrowableDeserializer;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.type.JavaType;
import com.fasterxml.jackson.databind.util.ClassUtil;
import com.fasterxml.jackson.databind.util.SimpleBeanPropertyDefinition;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

public class BeanDeserializerFactory_addBeanProps_TriageGen1Test {

    private BeanDeserializerFactory factory;
    private DeserializationContext ctxt;
    private BeanDescription beanDesc;
    private BeanDeserializerBuilder builder;
    private DeserializationConfig config;
    private DeserializerFactoryConfig factoryConfig;

    // Subclass to access protected method
    private static class TestableBeanDeserializerFactory extends BeanDeserializerFactory {
        public TestableBeanDeserializerFactory(DeserializerFactoryConfig config) {
            super(config);
        }

        @Override
        public void addBeanProps(DeserializationContext ctxt, BeanDescription beanDesc, BeanDeserializerBuilder builder) 
                throws JsonMappingException {
            super.addBeanProps(ctxt, beanDesc, builder);
        }
    }

    @Before
    public void setUp() {
        factoryConfig = mock(DeserializerFactoryConfig.class);
        factory = new TestableBeanDeserializerFactory(factoryConfig);
        ctxt = mock(DeserializationContext.class);
        beanDesc = mock(BeanDescription.class);
        builder = mock(BeanDeserializerBuilder.class);
        config = mock(DeserializationConfig.class);

        when(ctxt.getConfig()).thenReturn(config);
        when(beanDesc.getType()).thenReturn(mock(JavaType.class));
        when(beanDesc.getBeanClass()).thenReturn(Object.class);
        when(factoryConfig.hasDeserializerModifiers()).thenReturn(false);
    }

    @Test
    public void testAddBeanProps_WithIgnoralsAndAnySetterMethod() throws Exception {
        // Setup ignorals
        JsonIgnoreProperties.Value ignorals = mock(JsonIgnoreProperties.Value.class);
        when(ignorals.getIgnoreUnknown()).thenReturn(true);
        when(ignorals.getIgnored()).thenReturn(Collections.singleton("ignoredProp"));
        when(config.getDefaultPropertyIgnorals(any(), any())).thenReturn(ignorals);

        // Setup any setter method
        AnnotatedMethod anySetter = mock(AnnotatedMethod.class);
        when(beanDesc.findAnySetter()).thenReturn(anySetter);

        // Mock property definitions
        BeanPropertyDefinition propDef = mock(BeanPropertyDefinition.class);
        when(propDef.hasSetter()).thenReturn(true);
        when(propDef.getSetter()).thenReturn(mock(AnnotatedMember.class));
        when(propDef.getName()).thenReturn("prop1");

        when(beanDesc.findProperties()).thenReturn(Collections.singletonList(propDef));

        // Mock filterBeanProps via spy or by ensuring it returns something
        TestableBeanDeserializerFactory spyFactory = spy(factory);
        doReturn(Collections.singletonList(propDef)).when(spyFactory).filterBeanProps(any(), any(), any(), any(), any());

        // Mock constructSettableProperty
        SettableBeanProperty settableProp = mock(SettableBeanProperty.class);
        doReturn(settableProp).when(spyFactory).constructSettableProperty(any(), any(), any(), any());
        doReturn(mock(ValueInstantiator.class)).when(builder).getValueInstantiator();
        when(builder.getValueInstantiator().getFromObjectArguments(any())).thenReturn(new SettableBeanProperty[0]);

        spyFactory.addBeanProps(ctxt, beanDesc, builder);

        verify(builder).setIgnoreUnknownProperties(true);
        verify(builder).addIgnorable("ignoredProp");
        verify(builder).setAnySetter(any());
        verify(builder).addProperty(settableProp);
    }

    @Test
    public void testAddBeanProps_WithAnySetterFieldAndIgnoredProperties() throws Exception {
        // No ignorals
        when(config.getDefaultPropertyIgnorals(any(), any())).thenReturn(null);

        // Any setter field
        AnnotatedField anySetterField = mock(AnnotatedField.class);
        when(beanDesc.findAnySetter()).thenReturn(null);
        when(beanDesc.findAnySetterField()).thenReturn(anySetterField);

        // Ignored property names (fallback when no any-setter)
        when(beanDesc.getIgnoredPropertyNames()).thenReturn(Collections.singletonList("fieldToIgnore"));

        // Mock property definitions
        BeanPropertyDefinition propDef = mock(BeanPropertyDefinition.class);
        when(propDef.hasSetter()).thenReturn(false);
        when(propDef.hasField()).thenReturn(true);
        when(propDef.getField()).thenReturn(mock(AnnotatedMember.class));
        when(propDef.getName()).thenReturn("fieldProp");

        when(beanDesc.findProperties()).thenReturn(Collections.singletonList(propDef));

        TestableBeanDeserializerFactory spyFactory = spy(factory);
        doReturn(Collections.singletonList(propDef)).when(spyFactory).filterBeanProps(any(), any(), any(), any(), any());
        doReturn(mock(JavaType.class)).when(propDef.getField()).getType();
        doReturn(mock(SettableBeanProperty.class)).when(spyFactory).constructSettableProperty(any(), any(), any(), any());
        when(builder.getValueInstantiator()).thenReturn(mock(ValueInstantiator.class));
        when(builder.getValueInstantiator().getFromObjectArguments(any())).thenReturn(new SettableBeanProperty[0]);

        spyFactory.addBeanProps(ctxt, beanDesc, builder);

        verify(builder).setAnySetter(any());
        verify(builder).addIgnorable("fieldToIgnore");
    }

    @Test
    public void testAddBeanProps_WithConstructorProperties() throws Exception {
        // Concrete type
        when(beanDesc.getType().isAbstract()).thenReturn(false);

        // Creator props
        SettableBeanProperty creatorProp = mock(CreatorProperty.class);
        when(creatorProp.getName()).thenReturn("id");
        SettableBeanProperty[] creatorProps = new SettableBeanProperty[]{creatorProp};

        ValueInstantiator vi = mock(ValueInstantiator.class);
        when(builder.getValueInstantiator()).thenReturn(vi);
        when(vi.getFromObjectArguments(any())).thenReturn(creatorProps);

        // Property definition with constructor param
        BeanPropertyDefinition propDef = mock(BeanPropertyDefinition.class);
        when(propDef.hasConstructorParameter()).thenReturn(true);
        when(propDef.getName()).thenReturn("id");
        when(propDef.hasSetter()).thenReturn(false);
        when(propDef.hasField()).thenReturn(false);
        when(propDef.hasGetter()).thenReturn(false);

        when(beanDesc.findProperties()).thenReturn(Collections.singletonList(propDef));

        TestableBeanDeserializerFactory spyFactory = spy(factory);
        doReturn(Collections.singletonList(propDef)).when(spyFactory).filterBeanProps(any(), any(), any(), any(), any());

        spyFactory.addBeanProps(ctxt, beanDesc, builder);

        verify(builder).addCreatorProperty(creatorProp);
    }

    @Test
    public void testAddBeanProps_MissingCreatorPropertyReportsError() throws Exception {
        when(beanDesc.getType().isAbstract()).thenReturn(false);
        SettableBeanProperty creatorProp = mock(CreatorProperty.class);
        when(creatorProp.getName()).thenReturn("correctName");
        when(builder.getValueInstantiator()).thenReturn(mock(ValueInstantiator.class));
        when(builder.getValueInstantiator().getFromObjectArguments(any())).thenReturn(new SettableBeanProperty[]{creatorProp});

        BeanPropertyDefinition propDef = mock(BeanPropertyDefinition.class);
        when(propDef.hasConstructorParameter()).thenReturn(true);
        when(propDef.getName()).thenReturn("wrongName");
        when(propDef.hasSetter()).thenReturn(false);
        when(propDef.hasField()).thenReturn(false);
        when(propDef.hasGetter()).thenReturn(false);

        when(beanDesc.findProperties()).thenReturn(Collections.singletonList(propDef));

        TestableBeanDeserializerFactory spyFactory = spy(factory);
        doReturn(Collections.singletonList(propDef)).when(spyFactory).filterBeanProps(any(), any(), any(), any(), any());

        spyFactory.addBeanProps(ctxt, beanDesc, builder);

        verify(ctxt).reportBadPropertyDefinition(eq(beanDesc), eq(propDef), anyString(), any(), any());
    }

    @Test
    public void testAddBeanProps_UseGettersAsSetters() throws Exception {
        when(ctxt.isEnabled(MapperFeature.USE_GETTERS_AS_SETTERS)).thenReturn(true);
        when(ctxt.isEnabled(MapperFeature.AUTO_DETECT_GETTERS)).thenReturn(true);

        BeanPropertyDefinition propDef = mock(BeanPropertyDefinition.class);
        when(propDef.hasSetter()).thenReturn(false);
        when(propDef.hasField()).thenReturn(false);
        when(propDef.hasGetter()).thenReturn(true);

        AnnotatedMethod getter = mock(AnnotatedMethod.class);
        when(getter.getRawType()).thenReturn(Map.class);
        when(propDef.getGetter()).thenReturn(getter);

        when(beanDesc.findProperties()).thenReturn(Collections.singletonList(propDef));

        TestableBeanDeserializerFactory spyFactory = spy(factory);
        doReturn(Collections.singletonList(propDef)).when(spyFactory).filterBeanProps(any(), any(), any(), any(), any());
        when(builder.getValueInstantiator()).thenReturn(mock(ValueInstantiator.class));
        when(builder.getValueInstantiator().getFromObjectArguments(any())).thenReturn(new SettableBeanProperty[0]);
        doReturn(mock(SettableBeanProperty.class)).when(spyFactory).constructSetterlessProperty(any(), any());

        spyFactory.addBeanProps(ctxt, beanDesc, builder);

        verify(spyFactory).constructSetterlessProperty(eq(ctxt), eq(beanDesc), eq(propDef));
    }

    @Test
    public void testAddBeanProps_WithDeserializerModifier() throws Exception {
        BeanDeserializerModifier mod = mock(BeanDeserializerModifier.class);
        when(factoryConfig.deserializerModifiers()).thenReturn(Collections.singletonList(mod));

        BeanPropertyDefinition propDef = mock(BeanPropertyDefinition.class);
        when(propDef.hasSetter()).thenReturn(true);
        when(propDef.getSetter()).thenReturn(mock(AnnotatedMember.class));
        when(propDef.getName()).thenReturn("p");

        when(beanDesc.findProperties()).thenReturn(Collections.singletonList(propDef));

        // Mock modifier behavior
        when(mod.updateProperties(any(), any(), any())).thenReturn(new ArrayList<>());

        TestableBeanDeserializerFactory spyFactory = spy(factory);
        doReturn(Collections.singletonList(propDef)).when(spyFactory).filterBeanProps(any(), any(), any(), any(), any());
        when(builder.getValueInstantiator()).thenReturn(mock(ValueInstantiator.class));
        when(builder.getValueInstantiator().getFromObjectArguments(any())).thenReturn(new SettableBeanProperty[0]);
        doReturn(mock(SettableBeanProperty.class)).when(spyFactory).constructSettableProperty(any(), any(), any(), any());

        spyFactory.addBeanProps(ctxt, beanDesc, builder);

        verify(mod).updateProperties(any(), any(), any());
    }

    @Test
    public void testAddBeanProps_AbstractTypeNoCreatorProps() throws Exception {
        when(beanDesc.getType().isAbstract()).thenReturn(true);

        BeanPropertyDefinition propDef = mock(BeanPropertyDefinition.class);
        when(propDef.hasConstructorParameter()).thenReturn(true);
        when(propDef.hasSetter()).thenReturn(false);
        when(propDef.hasField()).thenReturn(false);
        when(propDef.hasGetter()).thenReturn(false);

        when(beanDesc.findProperties()).thenReturn(Collections.singletonList(propDef));

        TestableBeanDeserializerFactory spyFactory = spy(factory);
        doReturn(Collections.singletonList(propDef)).when(spyFactory).filterBeanProps(any(), any(), any(), any(), any());

        spyFactory.addBeanProps(ctxt, beanDesc, builder);
        // Since it's abstract, creatorProps is null, so it skips the constructor param logic
        verify(builder, never()).addCreatorProperty(any());
    }
}
